<script setup lang="ts">const route=useRoute(),{lang,local}=useLocale(); const {data:country,error}=await useFetch<any>(`/api/catalog/countries/${route.params.id}`); if(error.value) throw createError({statusCode:404}); const {data:numbers}=await useFetch<any[]>('/api/numbers',{query:{country:route.params.id}}); const name=computed(()=>lang.value==='ru'?country.value?.nameRu:country.value?.nameEn); usePageSeo(computed(()=>`${name.value}: ${lang.value==='ru'?'принять SMS онлайн':'receive SMS online'}`),computed(()=>lang.value==='ru'?`Публичные временные номера ${name.value} для просмотра SMS-кодов онлайн.`:`Public temporary ${name.value} numbers for viewing SMS codes online.`))</script>
<template><div class="shell page"><nav class="crumbs"><NuxtLink :to="local('/countries')">{{lang==='ru'?'Страны':'Countries'}}</NuxtLink> / {{name}}</nav><div class="country-title"><img :src="`/images/countries/${country.id}.svg`"><div><span class="kicker">{{country.phoneCode}} / Live feed</span><h1>{{name}}</h1></div></div><p class="lead">{{lang==='ru'?`Откройте публичный номер ${name} и просмотрите демонстрационную ленту последних сообщений. Набор обновляется каждый час, чтобы каталог оставался актуальным. Публичная лента подходит только для знакомства с форматом сервиса.`:`Open a public ${name} number and browse the latest simulated messages. The set refreshes hourly so the catalog stays current. The public feed is intended only for exploring how the service works.`}}</p><div class="number-grid"><NumberCard v-for="n in numbers" :key="n.id" :number="n"/></div><PremiumBanner medium="number_expired"/><SeoCopy :subject="name" type="country"/></div></template>
